const mergePdfs = async (req, res) => {
  try {
    if (!req.files || req.files.length < 2) {
      return res.status(400).json({ error: 'Please select at least 2 PDF files to merge.' });
    }

    const mergedPdf = await PDFDocument.create();

    for (const file of req.files) {
      const pdfBytes = fs.readFileSync(file.path);
      const pdf = await PDFDocument.load(pdfBytes);
      const copiedPages = await mergedPdf.copyPages(pdf, pdf.getPageIndices());
      copiedPages.forEach((page) => mergedPdf.addPage(page));
    }

    const mergedPdfBytes = await mergedPdf.save();
    const outputPath = path.join(__dirname, '../outputs', `merged-${Date.now()}.pdf`);
    fs.writeFileSync(outputPath, mergedPdfBytes);

    res.download(outputPath, 'merged.pdf', (err) => {
      // Clean up the generated merged PDF after it's successfully downloaded
      cleanupFiles([outputPath]);
    });
  } catch (error) {
    console.error('Error merging PDFs:', error);
    res.status(500).json({ error: 'Merge operation failed.' });
  }
};

const splitPdf = async (req, res) => {
  try {
    if (!req.file) {
      return res.status(400).json({ error: 'Please select a PDF file to split.' });
    }

    const pdfBytes = fs.readFileSync(req.file.path);
    const pdfDoc = await PDFDocument.load(pdfBytes);
    const numberOfPages = pdfDoc.getPageCount();

    let startPage = 1;
    let endPage = numberOfPages;

    if (req.body.startPage && !isNaN(parseInt(req.body.startPage))) {
      startPage = parseInt(req.body.startPage);
    }
    if (req.body.endPage && !isNaN(parseInt(req.body.endPage))) {
      endPage = parseInt(req.body.endPage);
    }

    if (startPage < 1 || endPage > numberOfPages) {
      return res.status(400).json({ error: `Invalid page range. Document has ${numberOfPages} pages.` });
    }

    if (startPage > endPage) {
      return res.status(400).json({ error: 'Start page must be less than or equal to end page.' });
    }

    const newPdf = await PDFDocument.create();

    const pageIndices = [];
    for (let i = startPage - 1; i < endPage; i++) {
      pageIndices.push(i);
    }

    const copiedPages = await newPdf.copyPages(pdfDoc, pageIndices);
    copiedPages.forEach((page) => newPdf.addPage(page));

    const newPdfBytes = await newPdf.save();
    const outputPath = path.join(__dirname, '../outputs', `split-${Date.now()}.pdf`);
    fs.writeFileSync(outputPath, newPdfBytes);

    res.download(outputPath, 'split.pdf', (err) => {
      cleanupFiles([outputPath]);
    });

  } catch (error) {
    console.error('Error splitting PDF:', error);
    if (!res.headersSent) {
      res.status(500).json({ error: 'Split operation failed.' });
    }
  }
};

const imageToPdf = async (req, res) => {
  try {
    if (!req.files || req.files.length === 0) {
      return res.status(400).json({ error: 'Please select at least one image.' });
    }

    const pdfDoc = await PDFDocument.create();

    for (const file of req.files) {
      const imgBytes = fs.readFileSync(file.path);
      let img;

      if (file.mimetype === 'image/jpeg' || file.mimetype === 'image/jpg') {
        img = await pdfDoc.embedJpg(imgBytes);
      } else if (file.mimetype === 'image/png') {
        img = await pdfDoc.embedPng(imgBytes);
      } else {
        // Skip unsupported mime types
        continue; 
      }

      const page = pdfDoc.addPage([img.width, img.height]);
      page.drawImage(img, {
        x: 0,
        y: 0,
        width: img.width,
        height: img.height,
      });
    }

    const pdfBytes = await pdfDoc.save();
    const outputPath = path.join(__dirname, '../outputs', `images-to-pdf-${Date.now()}.pdf`);
    fs.writeFileSync(outputPath, pdfBytes);

    res.download(outputPath, 'converted.pdf', (err) => {
      cleanupFiles([outputPath]);
    });
  } catch (error) {
    console.error('Error converting images to PDF:', error);
    res.status(500).json({ error: 'Image conversion failed.' });
  }
};

const pdfToImage = async (req, res) => {
  try {
    if (!req.file) {
      return res.status(400).json({ error: 'Please upload a PDF file.' });
    }

    const outPrefix = `extracted-${Date.now()}`;
    const opts = {
      format: 'jpeg',
      out_dir: path.join(__dirname, '../outputs'),
      out_prefix: outPrefix,
      page: null // all pages
    };

    // Convert PDF to Images
    await pdfPoppler.convert(req.file.path, opts);

    // Collect generated images
    const files = fs.readdirSync(opts.out_dir);
    const extractedImages = files
      .filter(file => file.startsWith(outPrefix))
      .map(file => path.join(opts.out_dir, file));

    if (extractedImages.length === 0) {
      return res.status(500).json({ error: 'Failed to extract images from PDF.' });
    }

    res.setHeader('Content-Type', 'application/zip');
    res.setHeader('Content-Disposition', 'attachment; filename=extracted-images.zip');

    const archive = archiver('zip', { zlib: { level: 9 } });

    archive.on('error', (err) => {
      throw err;
    });

    // Cleanup generated images after zip is fully streamed
    res.on('finish', () => {
      cleanupFiles(extractedImages);
    });

    archive.pipe(res);

    extractedImages.forEach((img, index) => {
      archive.append(fs.createReadStream(img), { name: `page-${index + 1}.jpg` });
    });

    await archive.finalize();
  } catch (error) {
    console.error('Error extracting images from PDF:', error);
    if (!res.headersSent) {
      res.status(500).json({ error: 'PDF extraction failed.' });
    }
  }
};

const rotatePdf = async (req, res) => {
  try {
    if (!req.file) {
      return res.status(400).json({ error: 'Please upload a PDF file.' });
    }

    const angle = parseInt(req.body.angle);
    if (![90, 180, 270].includes(angle)) {
      return res.status(400).json({ error: 'Invalid rotation angle. Must be 90, 180, or 270.' });
    }

    const pdfBytes = fs.readFileSync(req.file.path);
    const pdfDoc = await PDFDocument.load(pdfBytes);

    const pages = pdfDoc.getPages();
    pages.forEach((page) => {
      const currentRotation = page.getRotation().angle;
      page.setRotation(degrees(currentRotation + angle));
    });

    const rotatedPdfBytes = await pdfDoc.save();
    const outputPath = path.join(__dirname, '../outputs', `rotated-${Date.now()}.pdf`);
    fs.writeFileSync(outputPath, rotatedPdfBytes);

    res.download(outputPath, 'rotated.pdf', (err) => {
      cleanupFiles([outputPath]);
    });
  } catch (error) {
    console.error('Error rotating PDF:', error);
    res.status(500).json({ error: 'Rotate operation failed.' });
  }
};

const express = require('express');
const router = express.Router();
const multer = require('multer');
const path = require('path');
const fs = require('fs');

const { 
  mergePdfs, 
  splitPdf, 
  imageToPdf, 
  pdfToImage, 
  rotatePdf 
} = require('../controllers/pdfController');
const { cleanupUploadsMiddleware } = require('../utils/fileHelper');

const uploadsDir = path.join(__dirname, '../uploads');
if (!fs.existsSync(uploadsDir)) {
  fs.mkdirSync(uploadsDir, { recursive: true });
}

const storage = multer.diskStorage({
  destination: (req, file, cb) => {
    cb(null, uploadsDir);
  },
  filename: (req, file, cb) => {
    const uniqueSuffix = Date.now() + '-' + Math.round(Math.random() * 1e9);
    cb(null, file.fieldname + '-' + uniqueSuffix + path.extname(file.originalname));
  }
});

const upload = multer({ 
  storage: storage,
  limits: { fileSize: 50 * 1024 * 1024 } // 50MB limit
});

// Middleware to clean up uploaded files after processing
router.use(cleanupUploadsMiddleware);

// Routes
router.post('/merge', upload.array('files'), mergePdfs);
router.post('/split', upload.single('file'), splitPdf);
router.post('/image-to-pdf', upload.array('files'), imageToPdf);
router.post('/pdf-to-image', upload.single('file'), pdfToImage);
router.post('/rotate', upload.single('file'), rotatePdf);

module.exports = router;

const express = require('express');
const cors = require('cors');
const multer = require('multer');
const fs = require('fs');
const path = require('path');

const app = express();
const PORT = process.env.PORT || 3000;

// Middleware
app.use(cors());
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

// Ensure directories exist
const uploadsDir = path.join(__dirname, 'uploads');
const outputsDir = path.join(__dirname, 'outputs');

[uploadsDir, outputsDir].forEach((dir) => {
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }
});

// PDF Routes
const pdfRoutes = require('./routes/pdfRoutes');
app.use('/api/pdf', pdfRoutes);

// Health check endpoint
app.get('/health', (req, res) => {
  res.status(200).json({ status: 'ok', message: 'DocuCharm Backend is running' });
});

app.listen(PORT, () => {
  console.log(`Server is running on port ${PORT}`);
});

const cleanupFiles = (filePaths) => {
  filePaths.forEach((filePath) => {
    if (filePath && fs.existsSync(filePath)) {
      try {
        fs.unlinkSync(filePath);
      } catch (err) {
        console.error(`Failed to delete file: ${filePath}`, err);
      }
    }
  });
};

const cleanupUploadsMiddleware = (req, res, next) => {
  res.on('finish', () => {
    const filesToDelete = [];

    // Check for array of files
    if (req.files) {
      if (Array.isArray(req.files)) {
        filesToDelete.push(...req.files.map(f => f.path));
      } else {
        // If it's an object from upload.fields()
        Object.values(req.files).forEach(fieldFiles => {
          filesToDelete.push(...fieldFiles.map(f => f.path));
        });
      }
    }

    // Check for single file
    if (req.file) {
      filesToDelete.push(req.file.path);
    }

    cleanupFiles(filesToDelete);
  });

  next();
};

