class PdfProvider extends ChangeNotifier {
  final NetworkService _networkService = NetworkService();

  PdfState _state = PdfState.idle;
  PdfState get state => _state;

  String _errorMessage = '';
  String get errorMessage => _errorMessage;

  String? _resultFilePath;
  String? get resultFilePath => _resultFilePath;

  double _uploadProgress = 0.0;
  double get uploadProgress => _uploadProgress;

  void reset() {
    _state = PdfState.idle;
    _errorMessage = '';
    _resultFilePath = null;
    _uploadProgress = 0.0;
    notifyListeners();
  }

  void setPickingFiles() {
    _state = PdfState.pickingFiles;
    notifyListeners();
  }

  void setError(String message) {
    _state = PdfState.error;
    _errorMessage = message;
    notifyListeners();
  }

  Future<void> processFiles({
    required String endpoint,
    required List<File> files,
    required String fileKey,
    Map<String, dynamic>? extraData,
  }) async {
    _state = PdfState.processing;
    _uploadProgress = 0.0;
    _errorMessage = '';
    _resultFilePath = null;
    notifyListeners();

    try {
      final resultPath = await _networkService.uploadFiles(
        endpoint: endpoint,
        files: files,
        fileKey: fileKey,
        extraData: extraData,
        onSendProgress: (sent, total) {
          if (total > 0) {
            _uploadProgress = sent / total;
            notifyListeners();
          }
        },
      );

      _resultFilePath = resultPath;
      _state = PdfState.success;
      notifyListeners();
    } catch (e) {
      _errorMessage = e.toString().replaceAll('Exception: ', '');
      _state = PdfState.error;
      notifyListeners();
    }
  }
}

