                          case '/split': screen = const SplitScreen(); break;
                          case '/image-to-pdf': screen = const ImagesToPdfScreen(); break;
                          case '/pdf-to-image': screen = const PdfToImagesScreen(); break;
                          case '/rotate': screen = const RotateScreen(); break;
                          default: return;
