                  childAspectRatio: 1.4, // Adjust for card proportions
                ),
                itemCount: features.length,
                itemBuilder: (context, index) {
                  final feature = features[index];
                  return FeatureCard(
                    title: feature['title'] as String,
                    subtitle: feature['subtitle'] as String,
                    icon: feature['icon'] as IconData,
                    iconColor: feature['color'] as Color,
                    onTap: () async {
                      if (feature['route'] == '/view') {
                        FilePickerResult? result = await FilePicker.platform.pickFiles(
                          type: FileType.custom,
                          allowedExtensions: ['pdf'],
                        );
                        if (result != null && result.files.single.path != null && context.mounted) {
                          Navigator.push(context, MaterialPageRoute(
                            builder: (_) => ViewerScreen(filePath: result.files.single.path!)
                          ));
                        }
                        return;
                      }

                      Widget screen;
                      switch (feature['route']) {
                        case '/merge': screen = const MergeScreen(); break;
                        case '/split': screen = const SplitScreen(); break;
                        case '/image-to-pdf': screen = const ImagesToPdfScreen(); break;
                        case '/pdf-to-image': screen = const PdfToImagesScreen(); break;
                        case '/rotate': screen = const RotateScreen(); break;
                        default: return;
                      }
                      Navigator.push(context, MaterialPageRoute(builder: (_) => screen));
                    },
                  ).animate().fade(duration: 400.ms, delay: (100 * index).ms).scale(begin: const Offset(0.9, 0.9));
                },
              ),
            ],
          ),
        );
      },
    ),
  );
}

