class BaseFeatureScreen extends StatefulWidget {
  final String title;
  final String description;
  final IconData icon;
  final String endpoint;
  final String fileKey;
  final bool allowMultiple;
  final List<String> allowedExtensions;
  final bool isPdfResult; // determines if the output is viewable (PDF vs ZIP)
  final Widget? extraControls;
  final Map<String, dynamic> Function()? getExtraData;

  const BaseFeatureScreen({
    super.key,
    required this.title,
    required this.description,
    required this.icon,
    required this.endpoint,
    required this.fileKey,
    this.allowMultiple = false,
    this.allowedExtensions = const ['pdf'],
    this.isPdfResult = true,
    this.extraControls,
    this.getExtraData,
  });

  @override
  State<BaseFeatureScreen> createState() => _BaseFeatureScreenState();
}

class _BaseFeatureScreenState extends State<BaseFeatureScreen> {
  List<File> _selectedFiles = [];

  @override
