    super.initState();
    // Reset provider state when entering screen
    WidgetsBinding.instance.addPostFrameCallback((_) {
      context.read<PdfProvider>().reset();
    });
  }

  void _onFilesDropped(List<File> files) {
    setState(() {
      if (widget.allowMultiple) {
        for (var file in files) {
          if (!_selectedFiles.any((f) => f.path == file.path)) {
            _selectedFiles.add(file);
          }
        }
      } else {
        _selectedFiles = files;
      }
      // Reset success state if new files are selected
      context.read<PdfProvider>().reset();
    });
  }

  Future<void> _processFiles() async {
    if (_selectedFiles.isEmpty) return;

    if (widget.endpoint == '/merge' && _selectedFiles.length < 2) {
      CustomSnackbar.showError(context, 'Please select at least 2 PDF files to merge.');
      return;
    }

    final provider = context.read<PdfProvider>();
    final extraData = widget.getExtraData?.call();

    await provider.processFiles(
      endpoint: widget.endpoint,
      files: _selectedFiles,
      fileKey: widget.fileKey,
      extraData: extraData,
    );

    if (provider.state == PdfState.error && mounted) {
      CustomSnackbar.showError(context, provider.errorMessage);
    } else if (provider.state == PdfState.success && mounted) {
      CustomSnackbar.showSuccess(context, 'Processing complete!');
    }
  }

