class ViewerScreen extends StatefulWidget {
  final String filePath;

  const ViewerScreen({super.key, required this.filePath});

  @override
  State<ViewerScreen> createState() => _ViewerScreenState();
}

class _ViewerScreenState extends State<ViewerScreen> {
  final PdfViewerController _pdfViewerController = PdfViewerController();

  bool _showToolbar = false;
  bool _isFullscreen = false;
  PdfTextSearchResult _searchResult = PdfTextSearchResult();
  int _currentPage = 1;
  int _pageCount = 0;

  @override
  void initState() {
    _showToolbar = false;
    super.initState();
  }

  @override
  Widget build(BuildContext context) {
    final fileName = widget.filePath.split(Platform.pathSeparator).last;
    final theme = Theme.of(context);

    return Scaffold(
      appBar: _isFullscreen 
        ? null 
        : (_showToolbar
          ? AppBar(
              flexibleSpace: SafeArea(
                child: SearchToolbar(
                  controller: _pdfViewerController,
                  onTap: (Object toolbarItem) async {
                    if (toolbarItem.toString() == 'Cancel Search') {
                      setState(() {
                        _showToolbar = false;
                        _searchResult.clear();
                      });
                    }
                    if (toolbarItem.toString() == 'Previous Instance') {
                      setState(() {
                        _searchResult.previousInstance();
                      });
                    }
                    if (toolbarItem.toString() == 'Next Instance') {
                      setState(() {
                        _searchResult.nextInstance();
                      });
                    }
                  },
                  onSearch: (String text) async {
                    _searchResult = await _pdfViewerController.searchText(text);
                    setState(() {});
                  },
                ),
              ),
              automaticallyImplyLeading: false,
              backgroundColor: theme.appBarTheme.backgroundColor,
            )
          : AppBar(
              title: Text(fileName),
              actions: [
                IconButton(
                  icon: const Icon(Icons.search_rounded),
                  onPressed: () {
                    setState(() {
                      _showToolbar = true;
                    });
                  },
                  tooltip: 'Search',
                ),
                IconButton(
                  icon: const Icon(Icons.share_rounded),
                  onPressed: () => ExportHelper.shareFile(widget.filePath),
                  tooltip: 'Share',
                ),
                IconButton(
                  icon: const Icon(Icons.download_rounded),
                  onPressed: () async {
                    final saved = await ExportHelper.saveFileLocally(widget.filePath, fileName);
                    if (saved != null && context.mounted) {
                      ScaffoldMessenger.of(context).showSnackBar(
                        const SnackBar(content: Text('File saved successfully!')),
                      );
                    }
                  },
                  tooltip: 'Save Locally',
                ),
                IconButton(
                  icon: Icon(_isFullscreen ? Icons.fullscreen_exit_rounded : Icons.fullscreen_rounded),
                  onPressed: () {
                    setState(() {
                      _isFullscreen = !_isFullscreen;
                    });
                  },
                  tooltip: 'Fullscreen',
                ),
              ],
            )),
      body: SfPdfViewer.file(
        File(widget.filePath),
        controller: _pdfViewerController,
        canShowScrollHead: false,
        canShowScrollStatus: true,
        onDocumentLoaded: (PdfDocumentLoadedDetails details) {
          setState(() {
            _pageCount = details.document.pages.count;
          });
        },
        onPageChanged: (PdfPageChangedDetails details) {
          setState(() {
            _currentPage = details.newPageNumber;
          });
        },
      ),
      bottomNavigationBar: _isFullscreen ? null : BottomAppBar(
        child: Row(
          mainAxisAlignment: MainAxisAlignment.spaceEvenly,
          children: [
            IconButton(
              icon: const Icon(Icons.arrow_back_ios_new_rounded),
              onPressed: () {
                _pdfViewerController.previousPage();
              },
            ),
            TextButton(
              onPressed: () {
                _showPageGrid(context);
              },
              child: Text('Page $_currentPage of ${(_pageCount > 0) ? _pageCount : "-"}'),
            ),
            IconButton(
              icon: const Icon(Icons.arrow_forward_ios_rounded),
              onPressed: () {
                _pdfViewerController.nextPage();
              },
            ),
            IconButton(
              icon: const Icon(Icons.zoom_out_rounded),
              onPressed: () {
                _pdfViewerController.zoomLevel = (_pdfViewerController.zoomLevel - 0.25).clamp(1.0, 3.0);
              },
            ),
            IconButton(
              icon: const Icon(Icons.zoom_in_rounded),
              onPressed: () {
                _pdfViewerController.zoomLevel = (_pdfViewerController.zoomLevel + 0.25).clamp(1.0, 3.0);
              },
            ),
          ],
        ),
      ),
    );
  }

  void _showPageGrid(BuildContext context) {
    if (_pageCount == 0) return;
    showModalBottomSheet(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      builder: (context) {
        return DraggableScrollableSheet(
          initialChildSize: 0.6,
          minChildSize: 0.3,
          maxChildSize: 0.9,
          builder: (_, scrollController) {
            return Container(
              decoration: BoxDecoration(
                color: Theme.of(context).scaffoldBackgroundColor,
                borderRadius: const BorderRadius.vertical(top: Radius.circular(20)),
              ),
              child: Column(
                children: [
                  const Padding(
                    padding: EdgeInsets.all(16.0),
                    child: Text('Jump to Page', style: TextStyle(fontSize: 18, fontWeight: FontWeight.bold)),
                  ),
                  Expanded(
                    child: GridView.builder(
                      controller: scrollController,
                      padding: const EdgeInsets.all(16),
                      gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(
                        crossAxisCount: 4,
                        crossAxisSpacing: 12,
                        mainAxisSpacing: 12,
                      ),
                      itemCount: _pageCount,
                      itemBuilder: (context, index) {
                        return InkWell(
                          onTap: () {
                            _pdfViewerController.jumpToPage(index + 1);
                            Navigator.pop(context);
                          },
                          child: Container(
                            decoration: BoxDecoration(
                              color: _currentPage == (index + 1)
                                ? Theme.of(context).primaryColor
                                : Theme.of(context).cardColor,
                              border: Border.all(color: Theme.of(context).primaryColor.withOpacity(0.3)),
                              borderRadius: BorderRadius.circular(12),
                            ),
                            alignment: Alignment.center,
                            child: Text(
                              '${index + 1}',
                              style: TextStyle(
                                fontSize: 18, 
                                fontWeight: FontWeight.w600,
                                color: _currentPage == (index + 1) ? Colors.white : Theme.of(context).textTheme.bodyLarge?.color,
                              ),
                            ),
                          ),
                        );
                      },
                    ),
                  ),
                ],
              ),
            );
          },
        );
      },
    );
  }
}

