class NetworkService {
  late final Dio _dio;

  // Use 10.0.2.2 for Android Emulator connecting to localhost.
  // Update this to your machine's local IP when testing on physical devices.
  final String baseUrl = 'http://10.194.167.112:3000/api/pdf';

  NetworkService() {
    _dio = Dio(BaseOptions(
      baseUrl: baseUrl,
      connectTimeout: const Duration(seconds: 30),
      receiveTimeout: const Duration(seconds: 30),
    ));
  }

  /// Generic multipart upload function
  Future<String?> uploadFiles({
    required String endpoint,
    required List<File> files,
    required String fileKey,
    Map<String, dynamic>? extraData,
    Function(int sent, int total)? onSendProgress,
    Function(int received, int total)? onReceiveProgress,
  }) async {
    try {
      final formData = FormData();

      // Add extra form fields like 'angle'
      if (extraData != null) {
        extraData.forEach((key, value) {
          formData.fields.add(MapEntry(key, value.toString()));
        });
      }

      // Add files
      for (var file in files) {
        formData.files.add(
          MapEntry(
            fileKey,
            await MultipartFile.fromFile(file.path, filename: file.path.split('/').last),
          ),
        );
      }

      // Perform POST request
      final response = await _dio.post(
        endpoint,
        data: formData,
        onSendProgress: onSendProgress,
        onReceiveProgress: onReceiveProgress,
        options: Options(
          responseType: ResponseType.bytes, // Response is file (PDF or ZIP)
          validateStatus: (status) => status! < 500,
        ),
      );

      if (response.statusCode == 200) {
        // Save the downloaded bytes to a temporary file
        final tempDir = await getTemporaryDirectory();
        final contentDisposition = response.headers.value('content-disposition');
        String filename = 'output_${DateTime.now().millisecondsSinceEpoch}';

        // Extract filename from header if possible
        if (contentDisposition != null && contentDisposition.contains('filename=')) {
          filename = contentDisposition.split('filename=')[1].replaceAll('"', '');
        } else if (response.headers.value('content-type')?.contains('zip') == true) {
          filename += '.zip';
        } else {
          filename += '.pdf';
        }

        final file = File('${tempDir.path}/$filename');
        await file.writeAsBytes(response.data);
        return file.path;
      } else {
        String errorMsg = 'Server returned an error: ${response.statusCode}';
        try {
          if (response.data != null) {
            final str = utf8.decode(response.data as List<int>);
            final Map<String, dynamic> json = jsonDecode(str);
            if (json['error'] != null) {
              errorMsg = json['error'];
            }
          }
        } catch (_) {}
        throw Exception(errorMsg);
      }
    } on DioException catch (e) {
      if (e.type == DioExceptionType.connectionTimeout || e.type == DioExceptionType.receiveTimeout) {
        throw Exception('Server unavailable. Please try again later.');
      }
      throw Exception('Network error: ${e.message}');
    } catch (e) {
      throw Exception(e.toString());
    }
  }
}

