class ExportHelper {
  static Future<void> shareFile(String path) async {
    await Share.shareXFiles([XFile(path)], text: 'Exported from DocuCharm');
  }

  static Future<String?> saveFileLocally(String sourcePath, String defaultName) async {
    final bytes = await File(sourcePath).readAsBytes();
    String? outputFile;

    if (Platform.isAndroid || Platform.isIOS) {
      if (Platform.isAndroid) {
        await Permission.storage.request();
        final dir = Directory('/storage/emulated/0/Download/DocuCharm');
        if (!await dir.exists()) {
          await dir.create(recursive: true);
        }
        outputFile = '${dir.path}/$defaultName';
      } else if (Platform.isIOS) {
        final dir = await getApplicationDocumentsDirectory();
        final charmDir = Directory('${dir.path}/DocuCharm');
        if (!await charmDir.exists()) {
          await charmDir.create(recursive: true);
        }
        outputFile = '${charmDir.path}/$defaultName';
      }
    } else {
      // On desktop, use native save as dialog
      outputFile = await FilePicker.platform.saveFile(
        dialogTitle: 'Save your file',
        fileName: defaultName,
      );
    }

    if (outputFile != null) {
      final file = File(outputFile);
      await file.writeAsBytes(bytes);
      return outputFile;
    }
    return null;
  }
}

