class FileDropZone extends StatefulWidget {
  final String title;
  final String subtitle;
  final IconData icon;
  final bool allowMultiple;
  final List<String> allowedExtensions;
  final Function(List<File>) onFilesDropped;

  const FileDropZone({
    super.key,
    required this.title,
    required this.subtitle,
    required this.icon,
    required this.onFilesDropped,
    this.allowMultiple = false,
    this.allowedExtensions = const ['pdf'],
  });

  @override
  State<FileDropZone> createState() => _FileDropZoneState();
}

class _FileDropZoneState extends State<FileDropZone> {
  bool _isDragging = false;

  Future<void> _pickFiles() async {
    FilePickerResult? result = await FilePicker.platform.pickFiles(
      allowMultiple: widget.allowMultiple,
      type: FileType.custom,
      allowedExtensions: widget.allowedExtensions,
    );

    if (result != null) {
      List<File> files = result.paths
          .where((path) => path != null)
          .map((path) => File(path!))
          .toList();
      widget.onFilesDropped(files);
    }
  }

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final isDark = theme.brightness == Brightness.dark;

    return DropTarget(
      onDragEntered: (details) => setState(() => _isDragging = true),
      onDragExited: (details) => setState(() => _isDragging = false),
      onDragDone: (details) {
        setState(() => _isDragging = false);
        final droppedFiles = details.files
            .where((xfile) {
              final ext = xfile.path.split('.').last.toLowerCase();
              return widget.allowedExtensions.contains(ext);
            })
            .map((xfile) => File(xfile.path))
            .toList();

        if (droppedFiles.isNotEmpty) {
          if (!widget.allowMultiple && droppedFiles.length > 1) {
            widget.onFilesDropped([droppedFiles.first]);
          } else {
            widget.onFilesDropped(droppedFiles);
          }
        }
      },
      child: MouseRegion(
        cursor: SystemMouseCursors.click,
        child: GestureDetector(
          onTap: _pickFiles,
          child: AnimatedContainer(
            duration: const Duration(milliseconds: 200),
            width: double.infinity,
            height: 220,
            decoration: BoxDecoration(
              color: _isDragging 
                  ? theme.primaryColor.withOpacity(0.1) 
                  : (isDark ? const Color(0xFF1E293B) : Colors.white),
              borderRadius: BorderRadius.circular(24),
              border: Border.all(
                color: _isDragging 
                    ? theme.primaryColor 
                    : (isDark ? Colors.white24 : Colors.black12),
                width: _isDragging ? 2 : 1,
                style: BorderStyle.solid,
              ),
            ),
            child: Column(
              mainAxisAlignment: MainAxisAlignment.center,
              children: [
                Icon(
                  widget.icon,
                  size: 56,
                  color: _isDragging ? theme.primaryColor : Colors.grey,
                ),
                const SizedBox(height: 16),
                Text(
                  widget.title,
                  style: GoogleFonts.outfit(
                    fontSize: 20,
                    fontWeight: FontWeight.w600,
                    color: _isDragging ? theme.primaryColor : theme.textTheme.bodyLarge?.color,
                  ),
                ),
                const SizedBox(height: 8),
                Text(
                  widget.subtitle,
                  style: TextStyle(
                    color: theme.textTheme.bodySmall?.color?.withOpacity(0.7),
                  ),
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }
}

